                raw_author = raw_author[9:].strip()  # "Words by " is 9 chars
            elif raw_author.lower().startswith("by "):
                raw_author = raw_author[3:].strip()
            # Keep only the name part (no trailing punctuation like commas)
            # Simple cleaning: split on common separators like "and", " & ", etc.
            # but spec says join with " and ". We'll extract the name phrase.
            # Remove trailing periods or commas that might be part of the name? Assume not.
            # Keep as is, but ensure no extra "Words by ..." remains.
            # If after cleaning it's empty, fallback to meta author
            if raw_author:
                # Remove possible trailing punctuation like '.' or ','
                raw_author = raw_author.rstrip('.').rstrip(',')
                # If there are multiple names separated by "and" or "&", keep as is
                # but ensure we don't include "and" inside? spec says join with " and "
                # The page shows "Words by Tobin Rusk" -> "Tobin Rusk"
                author = raw_author
        # fallback to meta author if byline not found
        if author is None:
            author_meta = soup_release.find("meta", {"name": "author"})
            if author_meta and author_meta.get("content"):
