                if raw_author:
                    raw_author = raw_author.rstrip('.').rstrip(',')
                    author = raw_author

        # Extract body: main text paragraphs inside .press-content or .press-article
        body = ""
        # Try .press-content first
        content_div = soup_release.find("div", class_="press-content")
        if content_div:
            paras = []
            for p in content_div.find_all("p"):
                txt = p.get_text(separator="\n", strip=True)
                if txt:
                    paras.append(txt)
            body = "\n\n".join(paras)
        else:
            # fallback: .press-article
            article = soup_release.find("div", class_="press-article")
            if article:
                paras = []
                for p in article.find_all("p"):
                    txt = p.get_text(separator="\n", strip=True)
                    if txt:
                        paras.append(txt)
                body = "\n\n".join(paras)
            else:
                # fallback: main <p>s
                main = soup_release.find("main")
                if main:
                    paras = []
                    for p in main.find_all("p"):
                        txt = p.get_text(separator="\n", strip=True)
                        if txt:
                            paras.append(txt)
                    body = "\n\n".join(paras)

        # Build record
        record = {
            "url": rel_url,
            "title": title,
            "date": date_str,  # should be string YYYY-MM-DD or None if missing
            "author": author if author else None,
            "body": body,
        }
        records.append(record)

    # Sort newest first by date (descending)
    def get_sort_key(rec):
        d = rec["date"]
        if d and isinstance(d, str) and len(d) == 10 and d[4] == "-" and d[7] == "-":
            try:
                return datetime.strptime(d, "%Y-%m-%d")
            except Exception:
                return datetime.min
        return datetime.min

    records.sort(key=get_sort_key, reverse=True)

    return records
