    # Sort newest first by date descending
    def sort_key(r):
        if r["date"]:
            try:
                return datetime.strptime(r["date"], "%Y-%m-%d").date()
            except Exception:
                return date.min
        return date.min

    records.sort(key=sort_key, reverse=True)
